6	## Define the ADI_USE_OOC_SYNTHESIS environment variable to enable out of context
7	#  synthesis
8	if {[info exists ::env(ADI_USE_OOC_SYNTHESIS)]} {
9	  if {[string equal $::env(ADI_USE_OOC_SYNTHESIS) n]} {
10	     set ADI_USE_OOC_SYNTHESIS 0
11	  } else {
12	     set ADI_USE_OOC_SYNTHESIS 1
13	  }
14	} elseif {![info exists ADI_USE_OOC_SYNTHESIS]} {
15	   set ADI_USE_OOC_SYNTHESIS 1
16	}
17	
18	## Set number of parallel out of context jobs through environment variable
19	if {![info exists ::env(ADI_MAX_OOC_JOBS)]} {
20	  set ADI_MAX_OOC_JOBS 4
21	} else {
22	  set ADI_MAX_OOC_JOBS $::env(ADI_MAX_OOC_JOBS)
23	}
24	
25	## Set to enable incremental compilation
26	set ADI_USE_INCR_COMP 1
27	
28	## Set to enable power optimization
29	set ADI_POWER_OPTIMIZATION 0
30	
31	## Set to generate .bin (for selmap)
32	if {![info exists ::env(ADI_GENERATE_BIN)]} {
33	  set ADI_GENERATE_BIN 0
34	} else {
35	  if {[string equal $::env(ADI_GENERATE_BIN) n]} {
36	     set ADI_GENERATE_BIN 0
37	  } else {
38	     set ADI_GENERATE_BIN 1
39	  }
40	}
41	
42	## Initialize global variables
43	set p_board "not-applicable"
44	set p_device "none"
45	set sys_zynq 1
46	
47	set p_prcfg_init ""
48	set p_prcfg_list ""
49	set p_prcfg_status ""
50	
51	# Importing XCVR related functions
52	source $ad_hdl_dir/projects/xcvr_wizard/scripts/adi_xcvr_xilinx.tcl
