54	## Creates a Xilinx project for a given board
55	#
56	# \param[project_name] - name of the project
57	# \param[mode] - if set non-project mode will be used, otherwise project mode
58	# flow, see UG892 for more information
59	# \param[parameter_list] - a list of global parameters (parameters of the
60	# system_top module)
61	#
62	# Supported carrier names are: ac701, vcu118, kcu105, zed, microzed, zc702,
63	# zc706, mitx405, zcu102.
64	#
65	proc adi_project {project_name {mode 0} {parameter_list {}} } {
66	
67	  set device ""
68	  set board ""
69	
70	  # Determine the device based on the board name
71	  if [regexp "_ac701" $project_name] {
72	    set device "xc7a200tfbg676-2"
73	    set board [lindex [lsearch -all -inline [get_board_parts] *ac701*] end]
74	  }
75	  if [regexp "_vcu118" $project_name] {
76	    set device "xcvu9p-flga2104-2L-e"
77	    set board [lindex [lsearch -all -inline [get_board_parts] *vcu118*] end]
78	  }
79	  if [regexp "_kcu105" $project_name] {
80	    set device "xcku040-ffva1156-2-e"
81	    set board [lindex [lsearch -all -inline [get_board_parts] *kcu105*] end]
82	  }
83	  if [regexp "_zed" $project_name] {
84	    set device "xc7z020clg484-1"
85	    set board [lindex [lsearch -all -inline [get_board_parts] *zed*] end]
86	  }
87	  if [regexp "_coraz7s" $project_name] {
88	    set device "xc7z007sclg400-1"
89	    set board "not-applicable"
90	  }
91	  if [regexp "_microzed" $project_name] {
92	    set device "xc7z010clg400-1"
93	    set board "not-applicable"
94	  }
95	  if [regexp "_zc702" $project_name] {
96	    set device "xc7z020clg484-1"
97	    set board [lindex [lsearch -all -inline [get_board_parts] *zc702*] end]
98	  }
99	  if [regexp "_zc706" $project_name] {
100	    set device "xc7z045ffg900-2"
101	    set board [lindex [lsearch -all -inline [get_board_parts] *zc706*] end]
102	  }
103	  if [regexp "_mitx045" $project_name] {
104	    set device "xc7z045ffg900-2"
105	    set board "not-applicable"
106	  }
107	  if [regexp "_zcu102" $project_name] {
108	    set device "xczu9eg-ffvb1156-2-e"
109	    set board [lindex [lsearch -all -inline [get_board_parts] *zcu102*] end]
110	  }
111	  if [regexp "_vmk180_es1" $project_name] {
112	    enable_beta_device xcvm*
113	    xhub::refresh_catalog [xhub::get_xstores xilinx_board_store]
114	    xhub::install [xhub::get_xitems xilinx.com:xilinx_board_store:vmk180_es:*] -quiet
115	    set_param board.repoPaths [get_property LOCAL_ROOT_DIR [xhub::get_xstores xilinx_board_store]]
116	    set device "xcvm1802-vsva2197-2MP-e-S-es1"
117	    set board [lindex [lsearch -all -inline [get_board_parts] *vmk180_es*] end]
118	  }
119	  if [regexp "_vmk180" $project_name] {
120	    set device "xcvm1802-vsva2197-2MP-e-S"
121	    set board [lindex [lsearch -all -inline [get_board_parts] *vmk180*] end]
122	  }
123	  if [regexp "_vck190" $project_name] {
124	    set device "xcvc1902-vsva2197-2MP-e-S"
125	    set board [lindex [lsearch -all -inline [get_board_parts] *vck190*] end]
126	  }
127	  if [regexp "_vpk180" $project_name] {
128	    set device "xcvp1802-lsvc4072-2MP-e-S"
129	    set board [lindex [lsearch -all -inline [get_board_parts] *vpk180*] end]
130	  }
131	  if [regexp "_vc709" $project_name] {
132	    set device "xc7vx690tffg1761-2"
133	    set board [lindex [lsearch -all -inline [get_board_parts] *vc709*] end]
134	  }
135	  if [regexp "_kv260" $project_name] {
136	    set device "xck26-sfvc784-2LV-c"
137	    set board [lindex [lsearch -all -inline [get_board_parts] *kv260*] end]
138	  }
139	  if [regexp "_k26" $project_name] {
140	    set device "xck26-sfvc784-2LVI-i"
141	    set board [lindex [lsearch -all -inline [get_board_parts] *k26*] end]
142	  }
143	
144	  adi_project_create $project_name $mode $parameter_list $device $board
145	}
