148	## Creates a Xilinx project.
149	#
150	# \param[project_name] - name of the project
151	# \param[mode] - if set non-project mode will be used, otherwise project mode
152	# flow, see UG892 for more information
153	# \param[parameter_list] - a list of global parameters (parameters of the
154	# system_top module)
155	# \param[device] - Canonical Xilinx device string
156	# \param[board] - board BSP name (optional)
157	#
158	proc adi_project_create {project_name mode parameter_list device {board "not-applicable"}}  {
159	
160	  global ad_hdl_dir
161	  global ad_ghdl_dir
162	  global ad_project_dir
163	  global p_board
164	  global p_device
165	  global sys_zynq
166	  global required_vivado_version
167	  global IGNORE_VERSION_CHECK
168	  global ADI_USE_OOC_SYNTHESIS
169	  global ADI_USE_INCR_COMP
170	  global use_smartconnect
171	
172	  if {![info exists ::env(ADI_PROJECT_DIR)]} {
173	    set actual_project_name $project_name
174	  } else {
175	    set actual_project_name "$::env(ADI_PROJECT_DIR)${project_name}"
176	  }
177	
178	  ## update the value of $p_device only if it was not already updated elsewhere
179	  if {$p_device eq "none"} {
180	    set p_device $device
181	  }
182	  set p_board $board
183	
184	  set use_smartconnect 1
185	  if [regexp "^xc7z" $p_device] {
186	    # SmartConnect has higher resource utilization and worse timing closure on older families
187	    set use_smartconnect 0
188	  }
189	
190	  if [regexp "^xc7z" $p_device] {
191	    set sys_zynq 1
192	  } elseif [regexp "^xck26" $p_device] {
193	    set sys_zynq 2
194	  } elseif [regexp "^xczu" $p_device]  {
195	    set sys_zynq 2
196	  } elseif [regexp "^xcv\[ecmph\]" $p_device]  {
197	    set sys_zynq 3
198	  } else {
199	    set sys_zynq 0
200	  }
201	
202	  set VIVADO_VERSION [version -short]
203	  if {$IGNORE_VERSION_CHECK} {
204	    if {[string compare $VIVADO_VERSION $required_vivado_version] != 0} {
205	      puts -nonewline "CRITICAL WARNING: vivado version mismatch; "
206	      puts -nonewline "expected $required_vivado_version, "
207	      puts -nonewline "got $VIVADO_VERSION.\n"
208	    }
209	  } else {
210	    if {[string compare $VIVADO_VERSION $required_vivado_version] != 0} {
211	      puts -nonewline "ERROR: vivado version mismatch; "
212	      puts -nonewline "expected $required_vivado_version, "
213	      puts -nonewline "got $VIVADO_VERSION.\n"
214	      puts -nonewline "This ERROR message can be down-graded to CRITICAL WARNING by setting ADI_IGNORE_VERSION_CHECK environment variable to 1. Be aware that ADI will not support you, if you are using a different tool version.\n"
215	      exit 2
216	    }
217	  }
218	
219	   if {[info exists ::env(ADI_MATLAB)]} {
220	    set ADI_MATLAB 1
221	    set actual_project_name "$ad_hdl_dir/vivado_prj"
222	    if {$mode != 0} {
223	        puts -nonewline "MATLAB builds do not support mode 2"
224	        exit 2
225	    }
226	  } else {
227	    set ADI_MATLAB 0
228	  }
229	
230	  if {$mode == 0} {
231	     set project_system_dir "${actual_project_name}.srcs/sources_1/bd/system"
232	     if {$ADI_MATLAB == 0} {
233	       create_project ${actual_project_name} . -part $p_device -force
234	     }
235	  } else {
236	    set project_system_dir "${actual_project_name}.srcs/sources_1/bd/system"
237	    create_project -in_memory -part $p_device
238	  }
239	
240	  if {$mode == 1} {
241	    file mkdir ${actual_project_name}.data
242	  }
243	
244	  if {$p_board ne "not-applicable"} {
245	    set_property board_part $p_board [current_project]
246	  }
247	
248	  if {$ADI_MATLAB == 0} {
249	    set lib_dirs $ad_hdl_dir/library
250	  } else {
251	    set lib_dirs [get_property ip_repo_paths [current_fileset]]
252	     lappend lib_dirs $ad_hdl_dir/library
253	  }
254	  if {[info exists ::env(ADI_GHDL_DIR)]} {
255	    if {$ad_hdl_dir ne $ad_ghdl_dir} {
256	      lappend lib_dirs $ad_ghdl_dir/library
257	    }
258	  }
259	
260	  # Set a common IP cache for all projects
261	  if {$ADI_USE_OOC_SYNTHESIS == 1} {
262	    if {[file exists $ad_hdl_dir/ipcache] == 0} {
263	      file mkdir $ad_hdl_dir/ipcache
264	    }
265	    config_ip_cache -import_from_project -use_cache_location $ad_hdl_dir/ipcache
266	  }
267	
268	  set_property ip_repo_paths $lib_dirs [current_fileset]
269	  update_ip_catalog
270	
271	  ## Load custom message severity definitions
272	
273	  if {![info exists ::env(ADI_DISABLE_MESSAGE_SUPPRESION)]} {
274	    source $ad_hdl_dir/projects/scripts/adi_xilinx_msg.tcl
275	  }
276	
277	  ## In Vivado there is a limit for the number of warnings and errors which are
278	  ## displayed by the tool for a particular error or warning; the default value
279	  ## of this limit is 100.
280	  ## Overrides the default limit to 2000.
281	  set_param messaging.defaultLimit 2000
282	
283	  # Set parameters of the top level file
284	  # Make the same parameters available to system_bd.tcl
285	  set proj_params [get_property generic [current_fileset]]
286	  foreach {param value} $parameter_list {
287	    lappend proj_params $param=$value
288	    set ad_project_params($param) $value
289	  }
290	  set_property generic $proj_params [current_fileset]
291	
292	  create_bd_design "system"
293	  source system_bd.tcl
294	
295	  save_bd_design
296	  validate_bd_design
297	
298	  if {$ADI_USE_OOC_SYNTHESIS == 1} {
299	    set_property synth_checkpoint_mode Hierarchical [get_files  $project_system_dir/system.bd]
300	  } else {
301	    set_property synth_checkpoint_mode None [get_files  $project_system_dir/system.bd]
302	  }
303	  generate_target {synthesis implementation} [get_files  $project_system_dir/system.bd]
304	  if {$ADI_USE_OOC_SYNTHESIS == 1} {
305	    export_ip_user_files -of_objects [get_files  $project_system_dir/system.bd] -no_script -sync -force -quiet
306	    create_ip_run [get_files  $project_system_dir/system.bd]
307	  }
308	  make_wrapper -files [get_files $project_system_dir/system.bd] -top
309	
310	  if {$mode == 0} {
311	    import_files -force -norecurse -fileset sources_1 $project_system_dir/hdl/system_wrapper.v
312	  } else {
313	    write_hwdef -file "${actual_project_name}.data/$project_name.hwdef"
314	  }
315	
316	  if {$ADI_USE_INCR_COMP == 1} {
317	    if {[file exists ./reference.dcp]} {
318	      set_property incremental_checkpoint ./reference.dcp [get_runs impl_1]
319	    }
320	  }
321	
322	}
323	
324	## Add source files to an existing project.
325	#
326	# \param[project_name] - name of the project
327	# \param[project_files] - list of project files
328	#
329	proc adi_project_files {project_name project_files} {
330	  global ADI_POST_ROUTE_POD_PRE_SCRIPT
331	  global ADI_POST_ROUTE_SCRIPT
332	
333	  foreach pfile $project_files {
334	    if {[string range $pfile [expr 1 + [string last . $pfile]] end] == "xdc"} {
335	      add_files -norecurse -fileset constrs_1 $pfile
336	    } else {
337	      add_files -norecurse -fileset sources_1 $pfile
338	    }
339	  }
340	
341	  if {[info exists ADI_POST_ROUTE_POD_PRE_SCRIPT]} {
342	    add_files -fileset utils_1 -norecurse ${ADI_POST_ROUTE_POD_PRE_SCRIPT}
343	  }
344	  if {[info exists ADI_POST_ROUTE_SCRIPT]} {
345	    add_files -fileset utils_1 -norecurse ${ADI_POST_ROUTE_SCRIPT}
346	  }
347	
348	  # NOTE: top file name is always system_top
349	  set_property top system_top [current_fileset]
350	}
351	
352	## Run an existing project (generate bit stream).
353	#
354	# \param[project_name] - name of the project
355	#
356	# Additional configuration flags are documented in docs/user_guide/build_hdl.rst
357	# at the "Available build flags and parameters" section.
358	proc adi_project_run {project_name} {
359	
360	  global ad_project_dir
361	  global sys_zynq
362	  global ADI_POWER_OPTIMIZATION
363	  global ADI_USE_OOC_SYNTHESIS
364	  global ADI_MAX_OOC_JOBS
365	  global ADI_GENERATE_BIN
366	  global ADI_POST_ROUTE_POD_PRE_SCRIPT
367	  global ADI_POST_ROUTE_SCRIPT
368	
369	  if {[info exists ::env(ADI_MAX_THREADS)]} {
370	    set_param general.maxThreads ${::env(ADI_MAX_THREADS)}
371	    puts "INFO: maxThreads set to ${::env(ADI_MAX_THREADS)}"
372	  }
373	
374	  if {![info exists ::env(ADI_PROJECT_DIR)]} {
375	    set actual_project_name $project_name
376	    set ad_project_dir ""
377	  } else {
378	    set actual_project_name "$::env(ADI_PROJECT_DIR)${project_name}"
379	    set ad_project_dir "$::env(ADI_PROJECT_DIR)"
380	  }
381	  if {[info exists ::env(ADI_SKIP_SYNTHESIS)]} {
382	    puts "Skipping synthesis"
383	    return
384	  }
385	
386	  if {$ADI_USE_OOC_SYNTHESIS == 1} {
387	    launch_runs -jobs $ADI_MAX_OOC_JOBS system_*_synth_1 synth_1
388	  } else {
389	    launch_runs synth_1
390	  }
391	  wait_on_run synth_1
392	  open_run synth_1
393	  report_timing_summary -file ${ad_project_dir}timing_synth.log
394	
395	  if {![info exists ::env(ADI_NO_BITSTREAM_COMPRESSION)] && ![info exists ADI_NO_BITSTREAM_COMPRESSION]} {
396	    set_property BITSTREAM.GENERAL.COMPRESS TRUE [current_design]
397	  }
398	
399	  if {$ADI_POWER_OPTIMIZATION == 1} {
400	  set_property STEPS.POWER_OPT_DESIGN.IS_ENABLED true [get_runs impl_1]
401	  set_property STEPS.POST_PLACE_POWER_OPT_DESIGN.IS_ENABLED true [get_runs impl_1]
402	  }
403	
404	  set_param board.repoPaths [get_property LOCAL_ROOT_DIR [xhub::get_xstores xilinx_board_store]]
405	
406	  if {[info exists ADI_POST_ROUTE_POD_PRE_SCRIPT]} {
407	    set_property STEPS.POST_ROUTE_PHYS_OPT_DESIGN.IS_ENABLED true [get_runs impl_1]
408	    set_property STEPS.POST_ROUTE_PHYS_OPT_DESIGN.TCL.PRE [ get_files ${ADI_POST_ROUTE_POD_PRE_SCRIPT} -of [get_fileset utils_1] ] [get_runs impl_1]
409	  }
410	  if {[info exists ADI_POST_ROUTE_SCRIPT]} {
411	    set_property STEPS.ROUTE_DESIGN.TCL.POST [ get_files ${ADI_POST_ROUTE_SCRIPT} -of [get_fileset utils_1] ] [get_runs impl_1]
412	  }
413	
414	  launch_runs impl_1 -to_step write_bitstream
415	  wait_on_run impl_1
416	  open_run impl_1
417	  report_timing_summary -warn_on_violation -file ${ad_project_dir}timing_impl.log
418	
419	  if {[info exists ::env(ADI_GENERATE_UTILIZATION)]} {
420	    set csv_file ${ad_project_dir}resource_utilization.csv
421	    if {[ catch {
422	      xilinx::designutils::report_failfast -csv -file $csv_file -transpose -no_header -ignore_pr -quiet
423	      set MMCM [llength [get_cells -hierarchical -filter { PRIMITIVE_TYPE =~ *MMCM* }]]
424	      set PLL [llength [get_cells -hierarchical -filter { PRIMITIVE_TYPE =~ *PLL* }]]
425	      set worst_slack_setup [get_property SLACK [get_timing_paths -setup]]
426	      set worst_slack_hold [get_property SLACK [get_timing_paths -hold]]
427	
428	      set fileRead [open $csv_file r]
429	      set lines [split [read $fileRead] "\n"]
430	      set names_line [lindex $lines end-3]
431	      set values_line [lindex $lines end-2]
432	      close $fileRead
433	
434	      set fileWrite [open $csv_file w]
435	      puts $fileWrite "$names_line,MMCM*,PLL*,Worst_Setup_Slack,Worst_Hold_Slack"
436	      puts $fileWrite "$values_line,$MMCM,$PLL,$worst_slack_setup,$worst_slack_hold"
437	      close $fileWrite
438	      } issue ] != 0 } {
439	        puts "GENERATE_REPORTS: tclapp::xilinx::designutils not installed"
440	      }
441	
442	      # Define a list of IPs for which to generate report utilization
443	      set IP_list {
444	        ad_ip_jesd_204_tpl_adc
445	        ad_ip_jesd_204_tpl_dac
446	        axi_jesd204_rx
447	        axi_jesd204_tx
448	        jesd204_rx
449	        jesd204_tx
450	        axi_adxcvr
451	        util_adxcvr
452	        axi_dmac
453	        util_cpack2
454	        util_upack2
455	      }
456	
457	      foreach IP_name $IP_list {
458		set output_file ${ad_project_dir}${IP_name}_resource_utilization.log
459	        file delete $output_file
460	        foreach IP_instance [ get_cells -quiet -hierarchical -filter " ORIG_REF_NAME =~ $IP_name || REF_NAME =~ $IP_name " ] {
461	          report_utilization -hierarchical -hierarchical_depth 1 -cells $IP_instance -file $output_file -append -quiet
462	          report_property $IP_instance -file $output_file -append -quiet
463	          set report_file [ open $output_file a ]
464	          puts $report_file "\n\n\n"
465	          close $report_file
466	        }
467	      }
468	    } else {
469	    puts "GENERATE_REPORTS: Resource utilization files won't be generated because ADI_GENERATE_UTILIZATION env var is not set"
470	  }
471	
472	  ## Extract IP ports and their properties
473	
474	  if {[info exists ::env(ADI_EXTRACT_PORTS)]} {
475	
476	    set p_output_file ports_properties.txt
477	
478	    # Define a list of IPs for which to generate the ports properties and nets report
479	    set P_IP_list {
480	      util_wfifo
481	      util_rfifo
482	      util_cpack2
483	      util_upack2
484	      ad_ip_jesd204_tpl_adc
485	      ad_ip_jesd204_tpl_dac
486	      rx_fir_decimator
487	      tx_fir_interpolator
488	      axi_ad9361
489	      axi_adrv9009
490	    }
491	
492	    set fileWrite [open $p_output_file w]
493	
494	    foreach P_IP_name $P_IP_list {
495	      foreach P_IP_instance [ get_cells -quiet -hierarchical -filter " ORIG_REF_NAME =~ $P_IP_name || REF_NAME =~ $P_IP_name " ] {
496	        set P_IP_instance_name [regsub -all {i_system_wrapper\/system_i\/} $P_IP_instance {}]
497		if { [regexp {adc_tpl_core} $P_IP_instance_name] } {
498	            set P_IP_INST  [regsub -all {\/adc_tpl_core/inst} $P_IP_instance_name {}]
499	            puts "$P_IP_INST\n"
500	        } elseif { [regexp {dac_tpl_core} $P_IP_instance_name] } {
501	            set P_IP_INST  [regsub -all {\/dac_tpl_core/inst} $P_IP_instance_name {}]
502	            puts "$P_IP_INST\n"
503	        } else {
504	            set P_IP_INST  [regsub -all {\/inst} $P_IP_instance_name {}]
505	            puts "$P_IP_INST\n"
506	        }
507	        puts $fileWrite "\n$P_IP_INST properties: \n"
508	        set list_of_IP_ports [ get_bd_pins -of_objects [get_bd_cells $P_IP_INST]]
509	        foreach IP_port $list_of_IP_ports {
510	          set pin_direction [get_property DIR [get_bd_pins $IP_port]]
511	          set pin_path [get_property PATH [get_bd_pins $IP_port]]
512	          set pin_path_name  [regsub {\/} $pin_path {}]
513	          set left [get_property LEFT [get_bd_pins $IP_port]]
514	          set right [get_property RIGHT [get_bd_pins $IP_port]]
515	          puts $fileWrite "direction $pin_direction \nMSB $left \nLSB $right \nname $pin_path_name"
516	          set net_info [get_bd_nets -of_objects [get_bd_pins $IP_port]]
517	          set net_name  [regsub -all {\/} $net_info {}]
518	          puts $fileWrite "net $net_name\n"
519	        }
520	      }
521	    }
522	    close $fileWrite
523	
524	  } else {
525	  puts "GENERATE_PORTS_REPORTS: IP ports properties and nets report files won't be generated because ADI_EXTRACT_PORTS env var is not set"
526	  }
527	
528	  if {[info exists ::env(ADI_GENERATE_XPA)]} {
529	    set csv_file ${ad_project_dir}power_analysis.csv
530	    set Layers "8to11"
531	    set CapLoad "20"
532	    set ToggleRate "15.00000"
533	    set StatProb "0.500000"
534	
535	    set_load $CapLoad [all_outputs]
536	    set_operating_conditions -board_layers $Layers
537	    set_switching_activity -default_toggle_rate $ToggleRate
538	    set_switching_activity -default_static_probability $StatProb
539	    set_switching_activity -type lut -toggle_rate $ToggleRate -static_probability $StatProb -all
540	    set_switching_activity -type register -toggle_rate $ToggleRate -static_probability $StatProb -all
541	    set_switching_activity -type shift_register -toggle_rate $ToggleRate -static_probability $StatProb -all
542	    set_switching_activity -type lut_ram -toggle_rate $ToggleRate -static_probability $StatProb -all
543	    set_switching_activity -type bram -toggle_rate $ToggleRate -static_probability $StatProb -all
544	    set_switching_activity -type dsp -toggle_rate $ToggleRate -static_probability $StatProb -all
545	    set_switching_activity -type gt_rxdata -toggle_rate $ToggleRate -static_probability $StatProb -all
546	    set_switching_activity -type gt_txdata -toggle_rate $ToggleRate -static_probability $StatProb -all
547	    set_switching_activity -type io_output -toggle_rate $ToggleRate -static_probability $StatProb -all
548	    set_switching_activity -type bram_enable -toggle_rate $ToggleRate -static_probability $StatProb -all
549	    set_switching_activity -type bram_wr_enable -toggle_rate $ToggleRate -static_probability $StatProb -all
550	    set_switching_activity -type io_bidir_enable -toggle_rate $ToggleRate -static_probability $StatProb -all
551	    report_power -file $csv_file
552	
553	    set fileRead [open $csv_file r]
554	    set filecontent [read $fileRead]
555	    set input_list [split $filecontent "\n"]
556	
557	    set TextList [lsearch -all -inline $input_list "*Total On-Chip Power (W)*"]
558	    set on_chip_pwr "[lindex [lindex $TextList 0] 6] W"
559	    set TextList [lsearch -all -inline $input_list "*Junction Temperature (C)*"]
560	    set junction_temp "[lindex [lindex $TextList 0] 5] *C"
561	    close $fileRead
562	
563	    set fileWrite [open $csv_file w]
564	    puts $fileWrite "On-chip_power,Junction_temp"
565	    puts $fileWrite "$on_chip_pwr,$junction_temp"
566	    close $fileWrite
567	  } else {
568	    puts "GENERATE_REPORTS: Power analysis files won't be generated because ADI_GENERATE_XPA env var is not set"
569	  }
570	
571	  # Look for undefined clocks which do not show up in the timing summary
572	  set timing_check [check_timing -override_defaults no_clock -no_header -return_string]
573	  if {[regexp { (\d+) register} $timing_check -> num_regs]} {
574	
575	    if {[info exist num_regs]} {
576	      if {$num_regs > 0} {
577	        puts "CRITICAL WARNING: There are $num_regs registers with no clocks !!! See no_clock.log for details."
578	        check_timing -override_defaults no_clock -verbose -file ${ad_project_dir}no_clock.log
579	      }
580	    }
581	
582	  } else {
583	    puts "CRITICAL WARNING: The search for undefined clocks failed !!!"
584	  }
585	
586	  file mkdir ${actual_project_name}.sdk
587	
588	  set timing_string $[report_timing_summary -return_string]
589	  if { [string match "*VIOLATED*" $timing_string] == 1 ||
590	       [string match "*Timing constraints are not met*" $timing_string] == 1} {
591	    write_hw_platform -fixed -force  -include_bit -file ${actual_project_name}.sdk/system_top_bad_timing.xsa
592	    # Generate .bin file only for non Versal designs
593	    if {$ADI_GENERATE_BIN == 1} {
594	      if {$sys_zynq == 3} {
595	        puts "Bin generation skipped, Versal families do not support it."
596	      } else {
597	        write_bitstream -bin_file ${actual_project_name}.sdk/system_top_bad_timing.bit
598	      }
599	    }
600	    return -code error [format "ERROR: Timing Constraints NOT met!"]
601	  } else {
602	    write_hw_platform -fixed -force  -include_bit -file ${actual_project_name}.sdk/system_top.xsa
603	    # Generate .bin file only for non Versal designs
604	    if {$ADI_GENERATE_BIN == 1} {
605	      if {$sys_zynq == 3} {
606	        puts "Bin generation skipped, Versal families do not support it."
607	      } else {
608	        write_bitstream -bin_file ${actual_project_name}.sdk/system_top.bit
609	      }
610	    }
611	  }
612	}
613	
614	## Run synthesis on an partial design; use it in Partial Reconfiguration flow.
615	#
616	# \param[project_name] - project name
617	# \param[prcfg_name] - name of the partial design
618	# \param[hdl_files] - hdl source of the partial design
619	# \param[xdc_files] - XDC constraint source of the partial design
620	#
621	proc adi_project_synth {project_name prcfg_name hdl_files {xdc_files ""}} {
622	
623	  global p_device
624	  global ad_project_dir
625	
626	  if {![info exists ::env(ADI_PROJECT_DIR)]} {
627	    set actual_project_name $project_name
628	  } else {
629	    set actual_project_name "$::env(ADI_PROJECT_DIR)${project_name}"
630	  }
631	
632	  set p_prefix "${actual_project_name}.data/$project_name"
633	
634	  if {$prcfg_name eq ""} {
635	
636	    read_verilog .srcs/sources_1/bd/system/hdl/system_wrapper.v
637	    read_verilog $hdl_files
638	    read_xdc $xdc_files
639	
640	    synth_design -mode default -top system_top -part $p_device > $p_prefix.synth.rds
641	    write_checkpoint -force $p_prefix.synth.dcp
642	    close_project
643	
644	  } else {
645	
646	    create_project -in_memory -part $p_device
647	    read_verilog $hdl_files
648	    synth_design -mode out_of_context -top "prcfg" -part $p_device > $p_prefix.${prcfg_name}_synth.rds
649	    write_checkpoint -force $p_prefix.${prcfg_name}_synth.dcp
650	    close_project
651	  }
652	}
653	
654	## Run implementation on an partial design; use it in Partial Reconfiguration
655	#  flow.
656	#
657	# \param[project_name] - project name
658	# \param[prcfg_name] - name of the partial design
659	# \param[xdc_files] - XDC constraint source of the partial design
660	#
661	proc adi_project_impl {project_name prcfg_name {xdc_files ""}} {
662	
663	  global p_device
664	  global p_prcfg_init
665	  global p_prcfg_list
666	  global p_prcfg_status
667	  global ad_project_dir
668	
669	  if {![info exists ::env(ADI_PROJECT_DIR)]} {
670	    set actual_project_name $project_name
671	  } else {
672	    set actual_project_name "$::env(ADI_PROJECT_DIR)${project_name}"
673	  }
674	
675	  set p_prefix "${actual_project_name}.data/$project_name"
676	
677	  if {$prcfg_name eq "default"} {
678	    set p_prcfg_status 0
679	    set p_prcfg_list ""
680	    set p_prcfg_init "$p_prefix.${prcfg_name}_impl.dcp"
681	    file mkdir $project_name.sdk
682	  }
683	
684	  if {$prcfg_name eq "default"} {
685	
686	    open_checkpoint $p_prefix.synth.dcp -part $p_device
687	    read_xdc $xdc_files
688	    read_checkpoint -cell i_prcfg $p_prefix.${prcfg_name}_synth.dcp
689	    set_property HD.RECONFIGURABLE 1 [get_cells i_prcfg]
690	    opt_design > $p_prefix.${prcfg_name}_opt.rds
691	    write_debug_probes -force $p_prefix.${prcfg_name}_debug_nets.ltx
692	    place_design > $p_prefix.${prcfg_name}_place.rds
693	    route_design > $p_prefix.${prcfg_name}_route.rds
694	
695	  } else {
696	
697	    open_checkpoint $p_prefix.default_impl_bb.dcp -part $p_device
698	    lock_design -level routing
699	    read_checkpoint -cell i_prcfg $p_prefix.${prcfg_name}_synth.dcp
700	    read_xdc $xdc_files
701	    opt_design > $p_prefix.${prcfg_name}_opt.rds
702	    place_design > $p_prefix.${prcfg_name}_place.rds
703	    route_design > $p_prefix.${prcfg_name}_route.rds
704	  }
705	
706	  write_checkpoint -force $p_prefix.${prcfg_name}_impl.dcp
707	  report_utilization -pblocks pb_prcfg -file $p_prefix.${prcfg_name}_utilization.rpt
708	  report_timing_summary -file $p_prefix.${prcfg_name}_timing_summary.rpt
709	
710	  if [expr [get_property SLACK [get_timing_paths]] < 0] {
711	    set p_prcfg_status 1
712	    puts "CRITICAL WARNING: Timing Constraints NOT met ($prcfg_name)!"
713	  }
714	
715	  write_checkpoint -force -cell i_prcfg $p_prefix.${prcfg_name}_prcfg_impl.dcp
716	  update_design -cell i_prcfg -black_box
717	  write_checkpoint -force $p_prefix.${prcfg_name}_impl_bb.dcp
718	  open_checkpoint $p_prefix.${prcfg_name}_impl.dcp -part $p_device
719	  write_bitstream -force -bin_file -file $p_prefix.${prcfg_name}.bit
720	  write_sysdef -hwdef $p_prefix.hwdef -bitfile $p_prefix.${prcfg_name}.bit -file $p_prefix.${prcfg_name}.hdf
721	  file copy -force $p_prefix.${prcfg_name}.hdf $project_name.sdk/system_top.${prcfg_name}.hdf
722	
723	  if {$prcfg_name ne "default"} {
724	    lappend p_prcfg_list "$p_prefix.${prcfg_name}_impl.dcp"
725	  }
726	
727	  if {$prcfg_name eq "default"} {
728	    file copy -force $p_prefix.${prcfg_name}.hdf $project_name.sdk/system_top.hdf
729	  }
730	}
731	
732	## Verify an implemented partial reconfiguration design, checks if all the
733	#  partial design are compatible with the base design.
734	#
735	# \param[project_name] - project name
736	#
737	proc adi_project_verify {project_name} {
738	
739	  # checkpoint for the default design
740	  global p_prcfg_init
741	  # list of checkpoints with all the PRs integrated into the default design
742	  global p_prcfg_list
743	  global p_prcfg_status
744	
745	  set p_prefix "${actual_project_name}.data/$project_name"
746	
747	  pr_verify -full_check -initial $p_prcfg_init \
748	    -additional $p_prcfg_list \
749	    -file $p_prefix.prcfg_verify.log
750	
751	  if {$p_prcfg_status == 1} {
752	    return -code error [format "ERROR: Timing Constraints NOT met!"]
753	  }
754	}
